    private static Anime animeGoRow(String base,Element link){String href=link.absUrl("href");if(href.isEmpty())href=absolute(base,link.attr("href"));Matcher m=Pattern.compile("/anime/([^?#]+?)-(\\d+)(?:[/?#].*)?$").matcher(href);if(!m.find())return null;Anime a=new Anime();a.source="animego";a.id=m.group(2);a.alias=href;a.title=link.attr("title").trim();Element box=link;for(int depth=0;depth<5&&box!=null;depth++,box=box.parent()){if(a.title.isEmpty()){Element title=box.selectFirst(".ani-grid__item-title,.ani-list__item-title,.h5,.card-title,.animes-list-item-title,.media-title,.title");if(title!=null)a.title=title.text().trim();}if(a.poster.isEmpty()){Element img=box.selectFirst(".ani-grid__item-picture img[src],.ani-list__item-picture img[src],img[src],img[data-src],img[data-original]");if(img!=null)a.poster=absolute(base,img.hasAttr("data-src")?img.attr("data-src"):img.hasAttr("data-original")?img.attr("data-original"):img.attr("src"));}}if(a.title.isEmpty())a.title=link.text().trim();if(a.title.length()>180)a.title=a.title.substring(0,180);if(a.title.isEmpty())return null;a.type="Аниме";a.status="published";String text=link.parent()==null?"":link.parent().text();Matcher y=Pattern.compile("(19|20)\\d{2}").matcher(text);if(y.find())a.year=Integer.parseInt(y.group());return a;}
    private static String animeGoContent(String raw){try{JSONObject j=new JSONObject(raw);if(j.has("content"))return j.optString("content",raw);JSONObject data=j.optJSONObject("data");if(data!=null&&data.has("content"))return data.optString("content",raw);}catch(Exception ignored){}return raw;}
    private static String absolute(String base,String value){try{if(value==null||value.trim().isEmpty())return "";value=value.trim().replace(" ","%20").replace("&amp;","&");if(value.startsWith("//"))value="https:"+value;return safeUrl(new URL(new URL(base),value).toString());}catch(Exception e){return "";}}
    private static String hostName(String link){try{String h=Uri.parse(link.startsWith("//")?"https:"+link:link).getHost();return h==null?"Плеер":h.replace("www.","");}catch(Exception e){return "Плеер";}}
    static String plain(String text){return Html.fromHtml(text==null?"":text,Html.FROM_HTML_MODE_LEGACY).toString().replaceAll("\\[/?[^\\]]+\\]","").trim();}
    static String plainName(String text){return (text==null?"":text).toLowerCase(Locale.ROOT).replaceAll("[^\\p{L}\\p{N}]+"," ").trim();}
