    private static Anime shikiAnime(JSONObject j){Anime a=new Anime();a.source="shikimori";a.id=j.optString("id");a.malId=j.optInt("malId",0);if(a.malId==0)try{a.malId=Integer.parseInt(a.id);}catch(Exception ignored){}a.title=j.optString("russian","");if(a.title.isEmpty())a.title=j.optString("name","Аниме");a.original=j.optString("name","");a.type=kind(j.optString("kind"));a.status=j.optString("status");a.episodes=j.optInt("episodes");a.score=j.optDouble("score",0);JSONObject date=j.optJSONObject("airedOn"),poster=j.optJSONObject("poster");a.year=date==null?0:date.optInt("year");a.poster=poster==null?"":safeUrl(poster.optString("mainUrl",poster.optString("originalUrl")));a.age=j.optString("rating").equals("pg_13")?"13+":j.optString("rating").startsWith("r")?"18+":"";genres(a,j.optJSONArray("genres"),"russian");return a;}
    private static Anime vostAnime(JSONObject j){Anime a=new Anime();a.source="animevost";a.id=j.optString("id");String raw=j.optString("title","Аниме"),clean=raw.replaceAll("\\s*\\[[^\\]]*\\]\\s*$","");String[] names=clean.split(" / ",2);a.title=names[0];a.original=names.length>1?names[1]:"";a.description=plain(j.optString("description"));a.poster=safeUrl(j.optString("urlImagePreview"));a.year=j.optInt("year");a.type=j.optString("type","Аниме");Matcher m=Pattern.compile("из\\s*(\\d+)").matcher(raw);if(m.find())a.episodes=Integer.parseInt(m.group(1));a.status="published";for(String g:j.optString("genre","").split(","))if(!g.trim().isEmpty()&&!a.genres.contains(g.trim()))a.genres.add(g.trim());return a;}
    private static Anime yummyAnime(JSONObject j){Anime a=new Anime();a.source="yummy";a.id=j.optString("anime_id");a.title=j.optString("title","Аниме");a.alias=j.optString("anime_url");a.year=j.optInt("year");a.description=plain(j.optString("description"));JSONObject p=j.optJSONObject("poster"),type=j.optJSONObject("type"),age=j.optJSONObject("min_age"),rat=j.optJSONObject("rating"),ids=j.optJSONObject("remote_ids"),eps=j.optJSONObject("episodes"),status=j.optJSONObject("anime_status");a.poster=p==null?"":safeUrl(p.optString("medium",p.optString("fullsize")));a.type=type==null?"Аниме":type.optString("shortname","Аниме");a.age=age==null?"":age.optString("title");a.score=rat==null?0:rat.optDouble("average",0);a.status=status==null?"":status.optString("alias");a.episodes=eps==null?j.optInt("ep_count"):eps.optInt("count");a.malId=ids==null?0:ids.optInt("myanimelist_id");if(a.malId<=0&&ids!=null)a.malId=ids.optInt("shikimori_id");a.kpId=ids==null?0:ids.optInt("kp_id");a.libriaAlias=ids==null?"":ids.optString("anilibria_alias","");a.blocked=j.optBoolean("blocked",false);genres(a,j.optJSONArray("genres"),"title");return a;}
    private static Anime amAnime(JSONObject j){Anime a=new Anime();a.source="animelib";a.id=j.optString("id");a.title=j.optString("rus_name",j.optString("name","Аниме"));a.original=j.optString("name",j.optString("eng_name",""));a.alias=j.optString("slug_url",a.id);JSONObject p=j.optJSONObject("cover"),type=j.optJSONObject("type"),age=j.optJSONObject("ageRestriction"),rating=j.optJSONObject("rating"),status=j.optJSONObject("status"),episodes=j.optJSONObject("episodes");a.poster=p==null?"":safeUrl(p.optString("default"));try{a.year=Integer.parseInt(j.optString("releaseDate","").substring(0,4));}catch(Exception ignored){}a.type=type==null?"Аниме":type.optString("label");a.age=age==null?"":age.optString("label");a.score=rating==null?j.optDouble("shiki_rate",0):rating.optDouble("average",0);a.status=status!=null&&status.optInt("id")==1?"ongoing":"released";a.malId=j.optInt("shiki_id");a.anilistId=j.optInt("anilist_id");a.blocked=j.optBoolean("is_licensed",false);a.description=prose(j.opt("summary"),0);a.episodes=episodes==null?j.optInt("episodes_count",0):episodes.optInt("count",0);genres(a,j.optJSONArray("genres"),"name");return a;}
    private static String prose(Object value,int depth){if(value==null||depth>12)return "";if(value instanceof String)return plain((String)value);if(!(value instanceof JSONObject))return "";JSONObject j=(JSONObject)value;if(j.has("text"))return j.optString("text");StringBuilder s=new StringBuilder();JSONArray a=j.optJSONArray("content");for(int i=0;a!=null&&i<a.length();i++){s.append(prose(a.opt(i),depth+1));if(j.optString("type").equals("doc"))s.append("\n\n");}return s.toString().trim();}
    private static Anime libriaAnime(JSONObject j){Anime a=new Anime();a.source="anilibria";a.id=j.optString("id");JSONObject name=j.optJSONObject("name"),poster=j.optJSONObject("poster"),type=j.optJSONObject("type"),age=j.optJSONObject("age_rating");a.title=name==null?"Аниме":name.optString("main","Аниме");a.original=name==null?"":name.optString("english");a.alias=j.optString("alias");a.year=j.optInt("year");a.type=type==null?"Аниме":type.optString("description","Аниме");JSONObject opt=poster==null?null:poster.optJSONObject("optimized");String path=opt==null?(poster==null?"":poster.optString("preview")):opt.optString("preview");a.poster=path.startsWith("/")?"https://anilibria.top"+path:safeUrl(path);a.age=age==null?"":age.optString("label");a.description=plain(j.optString("description"));a.episodes=j.optInt("episodes_total");a.status=j.optBoolean("is_ongoing")?"ongoing":"released";a.blocked=j.optBoolean("is_blocked_by_geo")||j.optBoolean("is_blocked_by_copyrights");genres(a,j.optJSONArray("genres"),"name");JSONArray eps=j.optJSONArray("episodes");for(int i=0;eps!=null&&i<eps.length();i++){JSONObject e=eps.optJSONObject(i);if(e==null)continue;Anime.Episode ep=new Anime.Episode();ep.id=e.optString("id");ep.number=e.optDouble("ordinal");ep.name=e.optString("name");ep.duration=e.optInt("duration");putStream(ep,480,e.optString("hls_480"));putStream(ep,720,e.optString("hls_720"));putStream(ep,1080,e.optString("hls_1080"));JSONObject op=e.optJSONObject("opening");if(op!=null){ep.openingStart=op.optInt("start");ep.openingEnd=op.optInt("stop");}a.episodeList.add(ep);}a.episodeList.sort(Comparator.comparingDouble(e->e.number));return a;}
    private static String kind(String value){switch(value.toLowerCase(Locale.ROOT)){case "tv":case "tv_short":return "ТВ";case "movie":return "Фильм";case "ona":return "ONA";case "ova":return "OVA";case "special":case "tv_special":return "Спешл";case "music":return "Клип";default:return "Аниме";}}
